pub trait CustomerSource { fn find(&self, id: &str) -> Result<Option<Customer>, SourceError>; }

pub fn enrich(msg: Order, src: &dyn CustomerSource, cache: &Cache<String, Option<Customer>>)
    -> Result<EnrichedOrder, SourceError> {
    let customer = cache.try_get_with(msg.customer_id.clone(), || src.find(&msg.customer_id))
        .map_err(|e| SourceError::Unavailable(e.to_string()))?;
    Ok(EnrichedOrder { customer_name: customer.as_ref().map(|c| c.name.clone()), ..msg.into() })
}

