impl<S> Layer<S> for EnrichLayer { type Service = Enrich<S>; /* ... */ }

impl<S, B> Service<Request<B>> for Enrich<S>
where S: Service<Request<B>> + Clone + Send + 'static {
    fn call(&mut self, mut req: Request<B>) -> Self::Future {
        let src = self.source.clone();
        Box::pin(async move {
            let id = req.headers()["x-customer-id"].to_str()?.to_owned();
            req.extensions_mut().insert(src.find(&id).await?);   // enrich the request
            self.inner.call(req).await
        })
    }
}
